/// <summary>
/// This class is an extension of the ReturnTable form data source SalesTable
/// </summary>
[ExtensionOf(formDataSourceStr(ReturnTable, SalesTable))]
final class METReturnTableFormDSSalesTable_Extension
{
}

Method.Source:
/// <summary>
/// This method is used to determine if the menu items should be enabled or disabled
/// </summary>
/// <returns>int</returns>
public int active()
{
    const str campbell = 'CCC';

    int ret = next active();

    FormRun formRun = this.formRun();

    FormControl     menuItemAdviceReport = formRun.design().controlName(formControlStr(ReturnTable, METPickupAdviceReport));
    FormDataSource  salesTableDataSource = SysFormDataSource::findDataSource(formRun, tableNum(SalesTable));
    SalesTable      salesTable           = salesTableDataSource.cursor() as SalesTable;
    InventLocation  inventLocationShip   = InventLocation::find(salesTable.InventLocationId);

    if (inventLocationShip.METCSDWarehouse == true || inventLocationShip.METWHSubEntity == campbell)
    {
        menuItemAdviceReport.enabled(true);
    }
    else
    {
        menuItemAdviceReport.enabled(false);
    }

    return ret;
}
